import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(p,'utf8'),json=p=>JSON.parse(read(p));
const programme=json('data/programa-diputacion-administrativo-2026.json');
assert.equal(programme.temas.length,40);
const closed=programme.cierreEditorialC1Bloques20261105;
assert.equal(closed.temasConCierreEditorialDemostrado,39);
assert.equal(closed.cuentaPendientesGlobal,82);
assert.equal(programme.temas.filter(t=>t.estado==='AUDITADO').length,39);
assert.equal(programme.temas[21].estado,'EN_AUDITORIA_ESTATUTOS_COMPLETOS_PENDIENTES');
assert.equal(programme.temas[39].estado,'AUDITADO');
assert.equal(programme.temas[39].cierreEditorialBloque20261106.certificacionIntegral,false);
const root='content/diputacion-toledo/tema-40/';
const bank=json(root+'preguntas.json'),mat=json(root+'matriz.json');
const manual=read(root+'manual.md'),source=read(root+'fuentes.md'),report=read('content/diputacion-toledo/cierre-editorial-40-2026-11-06.md'),oapgt=read('content/diputacion-toledo/tema-22/fuentes.md');
assert.equal(bank.estado,'AUDITADO');assert.equal(mat.estado,'AUDITADO');
assert.equal(bank.cierreEditorialC1_T40_20261106.certificacionIntegral,false);
assert.equal(bank.cierreEditorialC1_T40_20261106.reformuladas,8);
assert.equal(mat.cierreEditorialC1_T40_20261106.reformuladas,8);
assert.equal(bank.preguntas.length,20);assert.equal(mat.controlCalidad.preguntas,20);
assert.equal(mat.trazabilidadIncisos.length,5);
assert.ok(manual.includes('## Epígrafe oficial'));
assert.ok(manual.includes('¡Foco Examen!'));
assert.ok(manual.includes('|---|'));
assert.ok(manual.includes('## Auditoría de supuestos prácticos'));
assert.ok(manual.includes('cierre-editorial-40-2026-11-06.md'));
assert.ok(source.includes('cierre-editorial-40-2026-11-06.md'));
assert.ok(oapgt.includes('Rastreo complementario de Estatutos OAPGT'));
const expected=[1,1,0,3,3,3,2,2,0,3,2,2,0,2,0,1,1,0,1,3];
let answers=0;
for(let i=0;i<20;i++){
 const q=bank.preguntas[i],id='DIP-T40-'+String(i+1).padStart(3,'0');
 assert.equal(q.id,id);assert.equal(q.correcta,expected[i]);assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones.map(s=>s.toLowerCase().trim())).size,4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion.length>25 && q.trampa.length>18 && q.referencia.length>20);
 assert.ok(report.includes(id));answers++;
}
assert.equal(answers*4,80);
const q=i=>bank.preguntas[i-1];
assert.ok(q(5).respuestaLiteral.includes('4 GiB menos 1 byte'));
assert.ok(q(8).respuestaLiteral.includes('4,7 GB'));
assert.ok(q(13).respuestaLiteral.includes('matricial'));
assert.ok(q(15).respuestaLiteral.includes('ppm mide velocidad'));
assert.ok(q(16).respuestaLiteral.includes('Extracción rápida'));
assert.ok(q(17).respuestaLiteral.includes('grabadora'));
assert.ok(q(18).respuestaLiteral.includes('controlador compatible'));
assert.ok(q(19).respuestaLiteral.includes('480 Mb/s'));
assert.ok(manual.includes('4.294.967.295 bytes'));
assert.ok(manual.includes('Mejor rendimiento'));
assert.ok(manual.includes('USB 3.2 ni USB4'));
